function InputSnapshot([string]$label){$frozen=Get-Content -LiteralPath $source -Raw|ConvertFrom-Json;$src=@(foreach($i in $frozen){$p=Join-Path $root $i.path;$h=Get-FileHash -LiteralPath $p -Algorithm SHA256;[pscustomobject]@{path=$i.path;sha256=$h.Hash;expected=$i.sha256;match=($h.Hash -eq $i.sha256)}});$files=@(Get-ChildItem -LiteralPath $cacheRoot -File -Recurse|ForEach-Object{$h=Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256;[pscustomobject]@{path=$_.FullName.Substring($cacheRoot.Length+1).Replace('\','/');bytes=$_.Length;sha256=$h.Hash}}|Sort-Object path);$dest="$prefix-inputs-$label.json";$files|ConvertTo-Json -Depth 4|Set-Content -LiteralPath $dest -Encoding UTF8;$stamps=@(Get-ChildItem -LiteralPath $venv -File -Recurse -Filter '*.stamp' -ErrorAction SilentlyContinue|ForEach-Object{$_.FullName});[pscustomobject]@{freeze_sha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash;source_files=$src;cache_files=$files.Count;cache_bytes=($files|Measure-Object bytes -Sum).Sum;cache_snapshot=$dest;venv_exists=(Test-Path -LiteralPath $venv);requirement_stamps=$stamps;cmake_sha256=(Get-FileHash -LiteralPath $cmake -Algorithm SHA256).Hash;cmake_version=(((& $cmake --version)|Select-Object -First 1)-join '')}}
