$env:LY_PACKAGE_SERVER_URLS=$null;$env:LY_PACKAGE_DOWNLOAD_CACHE_LOCATION=$null;$env:LY_PACKAGE_UNPACK_PATH=$null;$env:LY_3RDPARTY_PATH=$null;$env:PIP_NO_INDEX='1';$env:PIP_CONFIG_FILE='NUL';$env:PIP_DISABLE_PIP_VERSION_CHECK='1';$env:PYTHONNOUSERSITE='1';$env:PYTHONDONTWRITEBYTECODE='1'
