$sw=[Diagnostics.Stopwatch]::StartNew();$output=& $cmake @argv 2>&1;$exit=$LASTEXITCODE;$sw.Stop();$output|Out-String|Set-Content -LiteralPath "$prefix.log" -Encoding UTF8;$exit|Set-Content -LiteralPath "$prefix.exitcode" -Encoding ASCII;('{0:N3}s' -f $sw.Elapsed.TotalSeconds)|Set-Content -LiteralPath "$prefix.elapsed.txt" -Encoding ASCII;$after=InputSnapshot 'after';$metaAfter=[pscustomobject]@{started=$meta.started;finished=(Get-Date).ToString('o');exitcode=$exit;elapsed_seconds=$sw.Elapsed.TotalSeconds;before=$meta.inputs_before;after=$after;missing_wheelhouse_exists_after=(Test-Path -LiteralPath $missing);venv_exists_after=(Test-Path -LiteralPath $venv)};$metaAfter|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-result.json" -Encoding UTF8;Write-Output ("exit=$exit elapsed={0:N3}s venv_exists={1} stamps={2}" -f $sw.Elapsed.TotalSeconds,(Test-Path $venv),@($after.requirement_stamps).Count)
